use std::env;
use std::fs;
use std::io::{self, Read, IsTerminal, Write};
use std::process::ExitCode;

mod cli;
mod lex;
mod ast;
mod parse;
mod interp;

fn main() -> ExitCode {
    let args: Vec<String> = env::args().collect();
    let (opts, rest) = match cli::parse(&args) {
        cli::ParseResult::Options(opts, rest) => (opts, rest),
        cli::ParseResult::Help => {
            print!("{}", cli::HELP);
            return ExitCode::from(0);
        }
        cli::ParseResult::Version => {
            print!("{}", cli::VERSION);
            return ExitCode::from(0);
        }
        cli::ParseResult::Error(msg) => {
            eprint!("{}", msg);
            return ExitCode::from(1);
        }
    };

    // Determine source: first rest arg if it exists and is a file,
    // else stdin.
    let (source_name, source_code, script_args): (String, Vec<u8>, Vec<String>) =
        if let Some((first, rest_args)) = rest.split_first() {
            match fs::read(first) {
                Ok(data) => (first.clone(), data, rest_args.to_vec()),
                Err(_) => {
                    // Fall back to stdin for script body if stdin is not a tty
                    let stdin = io::stdin();
                    if stdin.is_terminal() {
                        // Would start REPL; we don't implement it; just exit 0
                        return ExitCode::from(0);
                    }
                    let mut buf = Vec::new();
                    let _ = stdin.lock().read_to_end(&mut buf);
                    ("<stdin>".to_string(), buf, rest.clone())
                }
            }
        } else {
            let stdin = io::stdin();
            if stdin.is_terminal() {
                // Would start REPL; we don't implement it
                return ExitCode::from(0);
            }
            let mut buf = Vec::new();
            let _ = stdin.lock().read_to_end(&mut buf);
            ("<stdin>".to_string(), buf, Vec::new())
        };

    // Lex the source.
    let lex_result = lex::lex(&source_code);

    if opts.lex {
        println!("--------------------------------------------------");
        for item in &lex_result.items {
            match item {
                lex::LexItem::Token(tok) => {
                    println!("{} (line {}, column {}):\t{}", source_name, tok.line, tok.column, tok.display());
                }
                lex::LexItem::Error(err) => {
                    println!("Error: line {}, column {} - {}", err.line, err.column, err.message);
                }
            }
        }
        println!("--------------------------------------------------");
    }

    // Collect lex errors for overall status reporting
    let mut has_lex_errors = false;
    for item in &lex_result.items {
        if let lex::LexItem::Error(err) = item {
            has_lex_errors = true;
            if !opts.lex {
                eprintln!("Error: {} (line {}, column {}) - {}", source_name, err.line, err.column, err.message);
            }
        }
    }

    // Parse
    let tokens: Vec<lex::Token> = lex_result.items.iter().filter_map(|i| match i {
        lex::LexItem::Token(t) => Some(t.clone()),
        _ => None,
    }).collect();

    let parse_result = parse::parse(&tokens);

    if opts.ast {
        println!("--------------------------------------------------");
        println!("AST for {}", source_name);
        if let Some(ref prog) = parse_result.program {
            ast::print(prog, &mut io::stdout()).ok();
        }
        println!("--------------------------------------------------");
    }

    if let Some(err) = &parse_result.error {
        if !opts.lex {
            eprintln!("Error: {}", err);
        } else {
            eprintln!("Error: {}", err);
        }
        return ExitCode::from(2);
    }

    if has_lex_errors {
        return ExitCode::from(2);
    }

    if opts.check {
        // Just static analysis (we do minimal analysis here).
        return ExitCode::from(0);
    }

    if opts.program {
        // We don't have a real bytecode compiler; skip.
    }

    // Execute
    if let Some(prog) = parse_result.program {
        let exit = interp::run(&prog, &source_name, &script_args);
        return ExitCode::from(exit);
    }

    ExitCode::from(0)
}
