pub const HELP: &str = "Hush 0.1.4\n\
gahag <gabriel.s.b@live.com>\n\
Hush is a unix shell scripting language based on the Lua programming language\n\
\n\
USAGE:\n    \
executable [FLAGS] [arguments]...\n\
\n\
FLAGS:\n\
        --ast        Print the AST\n\
        --check      Perform only static analysis instead of executing.\n\
    -h, --help       Prints help information\n\
        --lex        Print the lexemes\n\
        --program    Print the PROGAM\n\
    -V, --version    Prints version information\n\
\n\
ARGS:\n    \
<arguments>...    Script and/or arguments\n";

pub const VERSION: &str = "Hush 0.1.4\n";

#[derive(Default, Debug)]
pub struct Options {
    pub ast: bool,
    pub check: bool,
    pub lex: bool,
    pub program: bool,
}

pub enum ParseResult {
    Options(Options, Vec<String>),
    Help,
    Version,
    Error(String),
}

/// Parse the command-line arguments.
/// Flags: --ast, --check, --lex, --program, -h/--help, -V/--version.
/// Non-flag args go to the argument list.
pub fn parse(args: &[String]) -> ParseResult {
    let mut opts = Options::default();
    let mut rest: Vec<String> = Vec::new();
    let mut rest_mode = false;

    let mut i = 1;
    while i < args.len() {
        let a = &args[i];
        if !rest_mode && a.starts_with("--") {
            match a.as_str() {
                "--" => rest_mode = true,
                "--ast" => opts.ast = true,
                "--check" => opts.check = true,
                "--lex" => opts.lex = true,
                "--program" => opts.program = true,
                "--help" => return ParseResult::Help,
                "--version" => return ParseResult::Version,
                _ => {
                    return ParseResult::Error(format!(
                        "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\
                        \n\
                        USAGE:\n    \
                        executable [FLAGS] [arguments]...\n\
                        \n\
                        For more information try --help\n",
                        a
                    ));
                }
            }
        } else if !rest_mode && a.starts_with('-') && a.len() > 1 {
            // short flags
            match a.as_str() {
                "-h" => return ParseResult::Help,
                "-V" => return ParseResult::Version,
                _ => {
                    return ParseResult::Error(format!(
                        "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\
                        \n\
                        USAGE:\n    \
                        executable [FLAGS] [arguments]...\n\
                        \n\
                        For more information try --help\n",
                        a
                    ));
                }
            }
        } else {
            rest.push(a.clone());
            rest_mode = true;
        }
        i += 1;
    }

    ParseResult::Options(opts, rest)
}
