                if i+1 < src.len() && src[i+1] == b'+' {
                    items.push(LexItem::Token(Token { kind: TokenKind::Concat, line, column: col }));
                    i += 2;
                } else {
                    items.push(LexItem::Token(Token { kind: TokenKind::Plus, line, column: col }));
                    i += 1;
                }
            }
            b'-' => {
                items.push(LexItem::Token(Token { kind: TokenKind::Minus, line, column: col }));
                i += 1;
            }
            b'*' => {
                items.push(LexItem::Token(Token { kind: TokenKind::Star, line, column: col }));
                i += 1;
            }
            b'/' => {
                items.push(LexItem::Token(Token { kind: TokenKind::Slash, line, column: col }));
                i += 1;
            }
            b'%' => {
                items.push(LexItem::Token(Token { kind: TokenKind::Percent, line, column: col }));
                i += 1;
            }
            b'(' => { items.push(LexItem::Token(Token { kind: TokenKind::LParen, line, column: col })); i += 1; }
            b')' => { items.push(LexItem::Token(Token { kind: TokenKind::RParen, line, column: col })); i += 1; }
            b'[' => { items.push(LexItem::Token(Token { kind: TokenKind::LBracket, line, column: col })); i += 1; }
            b']' => { items.push(LexItem::Token(Token { kind: TokenKind::RBracket, line, column: col })); i += 1; }
            b'{' => { items.push(LexItem::Token(Token { kind: TokenKind::LBrace, line, column: col })); i += 1; }
            b',' => { items.push(LexItem::Token(Token { kind: TokenKind::Comma, line, column: col })); i += 1; }
            b'.' => { items.push(LexItem::Token(Token { kind: TokenKind::Dot, line, column: col })); i += 1; }
            b':' => { items.push(LexItem::Token(Token { kind: TokenKind::Colon, line, column: col })); i += 1; }
            b';' => { items.push(LexItem::Token(Token { kind: TokenKind::Semicolon, line, column: col })); i += 1; }
            b'=' => {
                if i+1 < src.len() && src[i+1] == b'=' {
                    items.push(LexItem::Token(Token { kind: TokenKind::EqEq, line, column: col }));
                    i += 2;
                } else {
                    items.push(LexItem::Token(Token { kind: TokenKind::Eq, line, column: col }));
                    i += 1;
                }
            }
            b'!' => {
                if i+1 < src.len() && src[i+1] == b'=' {
                    items.push(LexItem::Token(Token { kind: TokenKind::NotEq, line, column: col }));
                    i += 2;
                } else {
                    items.push(LexItem::Error(LexError { line, column: col, message: "unexpected '!'.".into() }));
                    i += 1;
                }
            }
            b'<' => {
                if i+1 < src.len() && src[i+1] == b'=' {
                    items.push(LexItem::Token(Token { kind: TokenKind::Le, line, column: col }));
                    i += 2;
                } else {
                    items.push(LexItem::Token(Token { kind: TokenKind::Lt, line, column: col }));
                    i += 1;
                }
            }
            b'>' => {
                if i+1 < src.len() && src[i+1] == b'=' {
                    items.push(LexItem::Token(Token { kind: TokenKind::Ge, line, column: col }));
                    i += 2;
                } else {
                    items.push(LexItem::Token(Token { kind: TokenKind::Gt, line, column: col }));
                    i += 1;
                }
            }
            b'@' => {
                if i+1 < src.len() && src[i+1] == b'[' {
                    items.push(LexItem::Token(Token { kind: TokenKind::AtBracket, line, column: col }));
                    i += 2;
                } else {
                    items.push(LexItem::Error(LexError { line, column: col, message: "unexpected '@'.".into() }));
                    i += 1;
                }
            }
            b'&' => {
                if i+1 < src.len() && src[i+1] == b'{' {
                    items.push(LexItem::Token(Token { kind: TokenKind::AndBrace, line, column: col }));
                    i += 2;
                } else {
                    items.push(LexItem::Token(Token { kind: TokenKind::Amp, line, column: col }));
                    i += 1;
                }
            }
            b'"' => {
                let start_line = line; let start_col = col;
                i += 1;
                let mut bytes: Vec<u8> = Vec::new();
                let mut terminated = false;
                while i < src.len() {
                    let b = src[i];
                    if b == b'"' { terminated = true; i += 1; break; }
                    if b == b'\n' { break; }
                    if b == b'\\' {
                        if i+1 < src.len() {
                            let e = src[i+1];
                            match e {
                                b'n' => bytes.push(b'\n'),
                                b'r' => bytes.push(b'\r'),
                                b't' => bytes.push(b'\t'),
                                b'\\' => bytes.push(b'\\'),
                                b'"' => bytes.push(b'"'),
                                b'\'' => bytes.push(b'\''),
                                b'0' => bytes.push(0),
                                _ => {
                                    bytes.push(b'\\');
                                    bytes.push(e);
                                }
                            }
                            i += 2;
                            continue;
                        }
                    }
                    bytes.push(b);
                    i += 1;
                }
                if !terminated {
                    items.push(LexItem::Error(LexError { line: start_line, column: start_col, message: "unterminated string".into() }));
                } else {
                    items.push(LexItem::Token(Token { kind: TokenKind::String(bytes), line: start_line, column: start_col }));
                }
            }
            b'\'' => {
                let start_line = line; let start_col = col;
                i += 1;
                let mut byte: Option<u8> = None;
                let mut terminated = false;
                if i < src.len() {
                    let b = src[i];
                    if b == b'\\' && i+1 < src.len() {
                        let e = src[i+1];
                        let decoded = match e {
                            b'n' => Some(b'\n'),
                            b'r' => Some(b'\r'),
                            b't' => Some(b'\t'),
                            b'\\' => Some(b'\\'),
                            b'"' => Some(b'"'),
                            b'\'' => Some(b'\''),
                            b'0' => Some(0),
                            _ => None,
                        };
                        if let Some(d) = decoded {
                            byte = Some(d);
                            i += 2;
                        } else {
                            // bad byte escape
                            items.push(LexItem::Error(LexError { line: start_line, column: start_col, message: format!("invalid byte escape '\\{}'.", e as char) }));
                            i += 2;
                        }
                    } else {
                        byte = Some(b);
                        i += 1;
                    }
                }
                if i < src.len() && src[i] == b'\'' {
                    terminated = true;
                    i += 1;
                }
                if !terminated {
                    items.push(LexItem::Error(LexError { line: start_line, column: start_col, message: "unterminated byte literal".into() }));
                } else if let Some(b) = byte {
                    items.push(LexItem::Token(Token { kind: TokenKind::Byte(b), line: start_line, column: start_col }));
                }
            }
            _ if is_digit(c) => {
                let start = i;
                let start_col = col;
                while i < src.len() && is_digit(src[i]) { i += 1; }
                let mut is_float = false;
                if i < src.len() && src[i] == b'.' && i+1 < src.len() && is_digit(src[i+1]) {
                    is_float = true;
                    i += 1;
                    while i < src.len() && is_digit(src[i]) { i += 1; }
                }
                if i < src.len() && (src[i] == b'e' || src[i] == b'E') {
                    is_float = true;
                    i += 1;
                    if i < src.len() && (src[i] == b'+' || src[i] == b'-') { i += 1; }
                    while i < src.len() && is_digit(src[i]) { i += 1; }
                }
                let text = std::str::from_utf8(&src[start..i]).unwrap_or("");
                if is_float {
                    let f: f64 = text.parse().unwrap_or(0.0);
                    // Hush seems to emit integer number even from 89e10 => 890000000000
                    // and 1.2e3 => 1200. So if result is integral, emit as int.
                    if f.fract() == 0.0 && f.abs() < 1e18 && !text.contains('.') {
                        items.push(LexItem::Token(Token { kind: TokenKind::Int(f as i64), line, column: start_col }));
                    } else if f.fract() == 0.0 && !text.contains('.') {
                        items.push(LexItem::Token(Token { kind: TokenKind::Int(f as i64), line, column: start_col }));
                    } else {
                        items.push(LexItem::Token(Token { kind: TokenKind::Float(f), line, column: start_col }));
                    }
                } else {
                    let n: i64 = text.parse().unwrap_or(0);
                    items.push(LexItem::Token(Token { kind: TokenKind::Int(n), line, column: start_col }));
                }
            }
            _ if is_ident_start(c) => {
                let start = i;
                let start_col = col;
                while i < src.len() && is_ident_cont(src[i]) { i += 1; }
                let text = std::str::from_utf8(&src[start..i]).unwrap_or("").to_string();
                let kind = match text.as_str() {
                    "let" => TokenKind::Let,
                    "if" => TokenKind::If,
                    "then" => TokenKind::Then,
                    "else" => TokenKind::Else,
                    "end" => TokenKind::End,
                    "while" => TokenKind::While,
                    "for" => TokenKind::For,
                    "in" => TokenKind::In,
                    "do" => TokenKind::Do,
                    "break" => TokenKind::Break,
                    "return" => TokenKind::Return,
                    "function" => TokenKind::Function,
                    "self" => TokenKind::Self_,
                    "true" => TokenKind::True,
                    "false" => TokenKind::False,
                    "nil" => TokenKind::Nil,
                    "not" => TokenKind::Not,
                    "and" => TokenKind::And,
                    "or" => TokenKind::Or,
                    _ => TokenKind::Ident(text),
                };
                items.push(LexItem::Token(Token { kind, line, column: start_col }));
            }
            _ => {
                items.push(LexItem::Error(LexError { line, column: col, message: format!("unexpected '{}'.", c as char) }));
                i += 1;
            }
        }
    }

    LexResult { items }
}
