                    "let" => TokenKind::Let,
                    "if" => TokenKind::If,
                    "then" => TokenKind::Then,
                    "else" => TokenKind::Else,
                    "end" => TokenKind::End,
                    "while" => TokenKind::While,
                    "for" => TokenKind::For,
                    "in" => TokenKind::In,
                    "do" => TokenKind::Do,
                    "break" => TokenKind::Break,
                    "return" => TokenKind::Return,
                    "function" => TokenKind::Function,
                    "self" => TokenKind::Self_,
                    "true" => TokenKind::True,
                    "false" => TokenKind::False,
                    "nil" => TokenKind::Nil,
                    "not" => TokenKind::Not,
                    "and" => TokenKind::And,
                    "or" => TokenKind::Or,
                    _ => TokenKind::Ident(text),
                };
                items.push(LexItem::Token(Token { kind, line, column: start_col }));
            }
            _ => {
                items.push(LexItem::Error(LexError { line, column: col, message: format!("unexpected '{}'.", c as char) }));
                i += 1;
            }
        }
    }

    LexResult { items }
}
