    Float(f64),
    String(Vec<u8>),  // raw bytes
    Byte(u8), // '\x00' single byte
    // Command-related tokens we treat specially (for lex display)
    Arg(Vec<u8>, Vec<String>), // arg with possible dollar-vars; we only need lex display
