            TokenKind::LtLt => "<<".into(),
            TokenKind::GtGt => ">>".into(),
            TokenKind::Amp => "&".into(),
            TokenKind::Ident(s) => s.clone(),
            TokenKind::Int(n) => n.to_string(),
            TokenKind::Float(n) => format_float(*n),
            TokenKind::String(b) => {
                let mut s = String::from("\"");
                s.push_str(&display_escape(b));
                s.push('"');
                s
            }
            TokenKind::Byte(b) => {
                let mut s = String::from("'");
                s.push_str(&display_escape(&[*b]));
                s.push('\'');
