fn format_float(f: f64) -> String {
    if f.is_nan() { return "nan".into(); }
    if f.is_infinite() { return if f < 0.0 { "-inf".into() } else { "inf".into() }; }
    let s = format!("{}", f);
    if s.contains('.') || s.contains('e') || s.contains('E') {
        s
    } else {
        format!("{}.0", s)
    }
}

fn display_escape(b: &[u8]) -> String {
    let mut out = String::new();
    for &ch in b {
        match ch {
            b'"' => out.push_str("\\\""),
            b'\\' => out.push_str("\\\\"),
            b'\n' => out.push_str("\\n"),
            b'\r' => out.push_str("\\r"),
            b'\t' => out.push_str("\\t"),
            0 => out.push_str("\\0"),
            0x20..=0x7e => out.push(ch as char),
            _ => {
                out.push_str(&format!("\\x{:02x}", ch));
            }
        }
    }
    out
}

#[derive(Debug, Clone)]
pub struct LexError {
    pub line: u32,
    pub column: u32,
