use std::io::{self, Write};

#[derive(Debug, Clone)]
pub enum Expr {
    Nil,
    Bool(bool),
    Int(i64),
    Float(f64),
    String(Vec<u8>),
    Byte(u8),
    Ident(String),
    // Self_ is an identifier "self"
    Array(Vec<Expr>),
    Dict(Vec<(String, Expr)>),
    Index(Box<Expr>, Box<Expr>),
    Field(Box<Expr>, String),
    Call(Box<Expr>, Vec<Expr>),
    UnOp(String, Box<Expr>),
    BinOp(String, Box<Expr>, Box<Expr>),
    Function(Vec<String>, Vec<Stmt>),
    If(Box<Expr>, Vec<Stmt>, Vec<Stmt>),
}

#[derive(Debug, Clone)]
pub enum Stmt {
    Let(String, Option<Expr>),
    Assign(Expr, Expr),
    Return(Option<Expr>),
    Break,
    ExprStmt(Expr),
    While(Expr, Vec<Stmt>),
    For(String, Expr, Vec<Stmt>),
    If(Expr, Vec<Stmt>, Vec<Stmt>),
}

pub type Program = Vec<Stmt>;

pub fn print(prog: &Program, w: &mut impl Write) -> io::Result<()> {
    for s in prog {
        print_stmt(s, 0, w)?;
    }
    Ok(())
}

fn indent(n: usize, w: &mut impl Write) -> io::Result<()> {
    for _ in 0..n { write!(w, "\t")?; }
    Ok(())
}

fn print_stmt(s: &Stmt, depth: usize, w: &mut impl Write) -> io::Result<()> {
    indent(depth, w)?;
    match s {
        Stmt::Let(name, None) => { writeln!(w, "let {}", name) }
        Stmt::Let(name, Some(e)) => {
            write!(w, "let {} = ", name)?;
            print_expr(e, depth, w)?;
            writeln!(w)
        }
        Stmt::Assign(lhs, rhs) => {
            print_expr(lhs, depth, w)?;
            write!(w, " = ")?;
            print_expr(rhs, depth, w)?;
            writeln!(w)
        }
        Stmt::Return(None) => writeln!(w, "return"),
        Stmt::Return(Some(e)) => {
            write!(w, "return ")?;
            print_expr(e, depth, w)?;
            writeln!(w)
        }
        Stmt::Break => writeln!(w, "break"),
        Stmt::ExprStmt(e) => {
            print_expr(e, depth, w)?;
            writeln!(w)
        }
        Stmt::While(cond, body) => {
            write!(w, "while ")?;
            print_expr(cond, depth, w)?;
            writeln!(w, " do")?;
            for s in body { print_stmt(s, depth+1, w)?; }
            indent(depth, w)?;
            writeln!(w, "end")
        }
        Stmt::For(name, iter, body) => {
            write!(w, "for {} in ", name)?;
            print_expr(iter, depth, w)?;
            writeln!(w, " do")?;
            for s in body { print_stmt(s, depth+1, w)?; }
            indent(depth, w)?;
            writeln!(w, "end")
        }
        Stmt::If(cond, t, e) => {
            write!(w, "if ")?;
            print_expr(cond, depth, w)?;
            writeln!(w, " then")?;
            for s in t { print_stmt(s, depth+1, w)?; }
            if !e.is_empty() {
                indent(depth, w)?;
                writeln!(w, "else")?;
                for s in e { print_stmt(s, depth+1, w)?; }
            }
            indent(depth, w)?;
            writeln!(w, "end")
        }
    }
}

pub fn print_expr(e: &Expr, depth: usize, w: &mut impl Write) -> io::Result<()> {
    match e {
        Expr::Nil => write!(w, "nil"),
        Expr::Bool(b) => write!(w, "{}", b),
        Expr::Int(n) => write!(w, "{}", n),
        Expr::Float(f) => {
            let s = format!("{}", f);
            if s.contains('.') || s.contains('e') || s.contains('E') { write!(w, "{}", s) } else { write!(w, "{}.0", s) }
        }
        Expr::String(b) => {
            write!(w, "\"")?;
            for &ch in b {
                match ch {
                    b'"' => write!(w, "\\\"")?,
                    b'\\' => write!(w, "\\\\")?,
                    b'\n' => write!(w, "\\n")?,
                    b'\r' => write!(w, "\\r")?,
                    b'\t' => write!(w, "\\t")?,
                    0 => write!(w, "\\0")?,
                    0x20..=0x7e => write!(w, "{}", ch as char)?,
                    _ => write!(w, "\\x{:02x}", ch)?,
                }
            }
