                }
                indent(depth, w)?;
                write!(w, "]")
            }
        }
        Expr::Index(base, ix) => {
            print_expr(base, depth, w)?;
            write!(w, "[")?;
            print_expr(ix, depth, w)?;
            write!(w, "]")
        }
        Expr::Field(base, name) => {
            print_expr(base, depth, w)?;
            write!(w, ".{}", name)
        }
        Expr::Call(base, args) => {
            print_expr(base, depth, w)?;
            write!(w, "(")?;
            for (i, a) in args.iter().enumerate() {
                if i > 0 { write!(w, ", ")?; }
                print_expr(a, depth, w)?;
            }
            write!(w, ")")
        }
        Expr::UnOp(op, inner) => {
            write!(w, "{}", op)?;
            if op.chars().all(|c| c.is_alphabetic()) { write!(w, " ")?; }
            print_expr(inner, depth, w)
        }
        Expr::BinOp(op, a, b) => {
            write!(w, "(")?;
            print_expr(a, depth, w)?;
            write!(w, " {} ", op)?;
            print_expr(b, depth, w)?;
            write!(w, ")")
        }
        Expr::Function(params, body) => {
            write!(w, "function(")?;
            for (i, p) in params.iter().enumerate() {
                if i > 0 { write!(w, ", ")?; }
                write!(w, "{}", p)?;
            }
            writeln!(w, ")")?;
            for s in body {
                print_stmt(s, depth+1, w)?;
            }
            indent(depth, w)?;
            write!(w, "end")
        }
        Expr::If(cond, t, e) => {
            write!(w, "if ")?;
            print_expr(cond, depth, w)?;
            writeln!(w, " then")?;
            for s in t { print_stmt(s, depth+1, w)?; }
            if !e.is_empty() {
                indent(depth, w)?;
                writeln!(w, "else")?;
                for s in e { print_stmt(s, depth+1, w)?; }
            }
            indent(depth, w)?;
            write!(w, "end")
        }
    }
}
