struct Parser<'a> {
    toks: &'a [Token],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn peek(&self) -> Option<&TokenKind> {
        self.toks.get(self.pos).map(|t| &t.kind)
    }
    fn peek_n(&self, n: usize) -> Option<&TokenKind> {
        self.toks.get(self.pos + n).map(|t| &t.kind)
    }
    fn bump(&mut self) -> Option<&Token> {
        let t = self.toks.get(self.pos);
        if t.is_some() { self.pos += 1; }
        t
    }
    fn consume(&mut self, k: &TokenKind) -> bool {
        if let Some(cur) = self.peek() {
            if std::mem::discriminant(cur) == std::mem::discriminant(k) {
                self.pos += 1;
                return true;
            }
        }
        false
    }
    fn expect(&mut self, k: &TokenKind, what: &str) -> Result<(), String> {
        if self.consume(k) { Ok(()) } else { Err(format!("expected {}", what)) }
    }

    fn parse_program(&mut self) -> Result<Program, String> {
        let mut stmts = Vec::new();
        while self.peek().is_some() {
            let s = self.parse_stmt()?;
            stmts.push(s);
            // consume optional semicolons
            while self.consume(&TokenKind::Semicolon) {}
        }
        Ok(stmts)
    }

    fn parse_stmt(&mut self) -> Result<Stmt, String> {
        match self.peek() {
            Some(TokenKind::Let) => {
                self.pos += 1;
                let name = self.parse_ident()?;
                if self.consume(&TokenKind::Eq) {
                    let e = self.parse_expr()?;
                    Ok(Stmt::Let(name, Some(e)))
                } else {
                    Ok(Stmt::Let(name, None))
                }
            }
            Some(TokenKind::Return) => {
                self.pos += 1;
                // Is there an expression?
                if matches!(self.peek(), None | Some(TokenKind::End) | Some(TokenKind::Semicolon) | Some(TokenKind::Else)) {
                    Ok(Stmt::Return(None))
                } else {
                    let e = self.parse_expr()?;
                    Ok(Stmt::Return(Some(e)))
                }
            }
            Some(TokenKind::Break) => { self.pos += 1; Ok(Stmt::Break) }
            Some(TokenKind::While) => {
                self.pos += 1;
                let cond = self.parse_expr()?;
                self.expect(&TokenKind::Do, "'do'")?;
                let body = self.parse_block(&[TokenKind::End])?;
                self.expect(&TokenKind::End, "'end'")?;
                Ok(Stmt::While(cond, body))
            }
            Some(TokenKind::For) => {
                self.pos += 1;
                let name = self.parse_ident()?;
                self.expect(&TokenKind::In, "'in'")?;
                let iter = self.parse_expr()?;
                self.expect(&TokenKind::Do, "'do'")?;
                let body = self.parse_block(&[TokenKind::End])?;
                self.expect(&TokenKind::End, "'end'")?;
                Ok(Stmt::For(name, iter, body))
            }
            _ => {
                // expression or assignment
                let e = self.parse_expr()?;
                if self.consume(&TokenKind::Eq) {
                    let rhs = self.parse_expr()?;
                    Ok(Stmt::Assign(e, rhs))
                } else {
                    Ok(Stmt::ExprStmt(e))
                }
            }
        }
    }

    fn parse_block(&mut self, stops: &[TokenKind]) -> Result<Vec<Stmt>, String> {
        let mut out = Vec::new();
        while let Some(k) = self.peek() {
            if stops.iter().any(|s| std::mem::discriminant(s) == std::mem::discriminant(k)) { break; }
            let s = self.parse_stmt()?;
            out.push(s);
            while self.consume(&TokenKind::Semicolon) {}
        }
        Ok(out)
    }

    fn parse_ident(&mut self) -> Result<String, String> {
        if let Some(tok) = self.toks.get(self.pos) {
            if let TokenKind::Ident(s) = &tok.kind {
                let s = s.clone();
                self.pos += 1;
                return Ok(s);
            }
        }
        Err("expected identifier".into())
    }

    fn parse_expr(&mut self) -> Result<Expr, String> {
        self.parse_or()
    }

    fn parse_or(&mut self) -> Result<Expr, String> {
        let mut lhs = self.parse_and()?;
        while matches!(self.peek(), Some(TokenKind::Or)) {
            self.pos += 1;
            let rhs = self.parse_and()?;
            lhs = Expr::BinOp("or".into(), Box::new(lhs), Box::new(rhs));
        }
        Ok(lhs)
    }
    fn parse_and(&mut self) -> Result<Expr, String> {
        let mut lhs = self.parse_not()?;
        while matches!(self.peek(), Some(TokenKind::And)) {
            self.pos += 1;
            let rhs = self.parse_not()?;
            lhs = Expr::BinOp("and".into(), Box::new(lhs), Box::new(rhs));
        }
        Ok(lhs)
    }
    fn parse_not(&mut self) -> Result<Expr, String> {
        if self.consume(&TokenKind::Not) {
            let inner = self.parse_not()?;
            Ok(Expr::UnOp("not".into(), Box::new(inner)))
        } else {
            self.parse_cmp()
        }
    }
    fn parse_cmp(&mut self) -> Result<Expr, String> {
        let mut lhs = self.parse_concat()?;
        loop {
            let op = match self.peek() {
                Some(TokenKind::EqEq) => "==",
                Some(TokenKind::NotEq) => "!=",
                Some(TokenKind::Lt) => "<",
                Some(TokenKind::Le) => "<=",
                Some(TokenKind::Gt) => ">",
                Some(TokenKind::Ge) => ">=",
                _ => break,
            };
            self.pos += 1;
            let rhs = self.parse_concat()?;
            lhs = Expr::BinOp(op.into(), Box::new(lhs), Box::new(rhs));
        }
        Ok(lhs)
    }
    fn parse_concat(&mut self) -> Result<Expr, String> {
        let mut lhs = self.parse_add()?;
        while matches!(self.peek(), Some(TokenKind::Concat)) {
            self.pos += 1;
            let rhs = self.parse_add()?;
            lhs = Expr::BinOp("++".into(), Box::new(lhs), Box::new(rhs));
        }
        Ok(lhs)
    }
    fn parse_add(&mut self) -> Result<Expr, String> {
        let mut lhs = self.parse_mul()?;
        loop {
            let op = match self.peek() {
                Some(TokenKind::Plus) => "+",
                Some(TokenKind::Minus) => "-",
                _ => break,
            };
            self.pos += 1;
            let rhs = self.parse_mul()?;
            lhs = Expr::BinOp(op.into(), Box::new(lhs), Box::new(rhs));
        }
        Ok(lhs)
    }
    fn parse_mul(&mut self) -> Result<Expr, String> {
        let mut lhs = self.parse_unary()?;
        loop {
            let op = match self.peek() {
                Some(TokenKind::Star) => "*",
                Some(TokenKind::Slash) => "/",
                Some(TokenKind::Percent) => "%",
                _ => break,
            };
            self.pos += 1;
            let rhs = self.parse_unary()?;
            lhs = Expr::BinOp(op.into(), Box::new(lhs), Box::new(rhs));
        }
        Ok(lhs)
    }
    fn parse_unary(&mut self) -> Result<Expr, String> {
        if self.consume(&TokenKind::Minus) {
            let inner = self.parse_unary()?;
            Ok(Expr::UnOp("-".into(), Box::new(inner)))
        } else {
            self.parse_postfix()
        }
    }
    fn parse_postfix(&mut self) -> Result<Expr, String> {
        let mut e = self.parse_atom()?;
        loop {
            match self.peek() {
                Some(TokenKind::Dot) => {
                    self.pos += 1;
                    let name = self.parse_ident()?;
                    e = Expr::Field(Box::new(e), name);
