    }

    fn parse_ident(&mut self) -> Result<String, String> {
        if let Some(tok) = self.toks.get(self.pos) {
            if let TokenKind::Ident(s) = &tok.kind {
                let s = s.clone();
                self.pos += 1;
                return Ok(s);
            }
        }
        Err("expected identifier".into())
    }

    fn parse_expr(&mut self) -> Result<Expr, String> {
        self.parse_or()
    }

    fn parse_or(&mut self) -> Result<Expr, String> {
        let mut lhs = self.parse_and()?;
        while matches!(self.peek(), Some(TokenKind::Or)) {
            self.pos += 1;
            let rhs = self.parse_and()?;
            lhs = Expr::BinOp("or".into(), Box::new(lhs), Box::new(rhs));
        }
        Ok(lhs)
    }
    fn parse_and(&mut self) -> Result<Expr, String> {
        let mut lhs = self.parse_not()?;
        while matches!(self.peek(), Some(TokenKind::And)) {
            self.pos += 1;
            let rhs = self.parse_not()?;
            lhs = Expr::BinOp("and".into(), Box::new(lhs), Box::new(rhs));
        }
        Ok(lhs)
    }
    fn parse_not(&mut self) -> Result<Expr, String> {
        if self.consume(&TokenKind::Not) {
            let inner = self.parse_not()?;
            Ok(Expr::UnOp("not".into(), Box::new(inner)))
        } else {
            self.parse_cmp()
        }
    }
    fn parse_cmp(&mut self) -> Result<Expr, String> {
        let mut lhs = self.parse_concat()?;
        loop {
            let op = match self.peek() {
                Some(TokenKind::EqEq) => "==",
                Some(TokenKind::NotEq) => "!=",
                Some(TokenKind::Lt) => "<",
                Some(TokenKind::Le) => "<=",
                Some(TokenKind::Gt) => ">",
                Some(TokenKind::Ge) => ">=",
                _ => break,
            };
            self.pos += 1;
            let rhs = self.parse_concat()?;
            lhs = Expr::BinOp(op.into(), Box::new(lhs), Box::new(rhs));
        }
        Ok(lhs)
    }
    fn parse_concat(&mut self) -> Result<Expr, String> {
        let mut lhs = self.parse_add()?;
        while matches!(self.peek(), Some(TokenKind::Concat)) {
            self.pos += 1;
            let rhs = self.parse_add()?;
            lhs = Expr::BinOp("++".into(), Box::new(lhs), Box::new(rhs));
        }
        Ok(lhs)
    }
    fn parse_add(&mut self) -> Result<Expr, String> {
        let mut lhs = self.parse_mul()?;
        loop {
            let op = match self.peek() {
                Some(TokenKind::Plus) => "+",
                Some(TokenKind::Minus) => "-",
                _ => break,
            };
            self.pos += 1;
            let rhs = self.parse_mul()?;
            lhs = Expr::BinOp(op.into(), Box::new(lhs), Box::new(rhs));
        }
        Ok(lhs)
    }
    fn parse_mul(&mut self) -> Result<Expr, String> {
        let mut lhs = self.parse_unary()?;
        loop {
            let op = match self.peek() {
                Some(TokenKind::Star) => "*",
                Some(TokenKind::Slash) => "/",
                Some(TokenKind::Percent) => "%",
                _ => break,
            };
            self.pos += 1;
            let rhs = self.parse_unary()?;
            lhs = Expr::BinOp(op.into(), Box::new(lhs), Box::new(rhs));
        }
        Ok(lhs)
    }
    fn parse_unary(&mut self) -> Result<Expr, String> {
        if self.consume(&TokenKind::Minus) {
            let inner = self.parse_unary()?;
            Ok(Expr::UnOp("-".into(), Box::new(inner)))
        } else {
            self.parse_postfix()
        }
    }
    fn parse_postfix(&mut self) -> Result<Expr, String> {
        let mut e = self.parse_atom()?;
        loop {
            match self.peek() {
                Some(TokenKind::Dot) => {
                    self.pos += 1;
                    let name = self.parse_ident()?;
                    e = Expr::Field(Box::new(e), name);
                }
                Some(TokenKind::LBracket) => {
                    self.pos += 1;
                    let ix = self.parse_expr()?;
                    self.expect(&TokenKind::RBracket, "']'")?;
                    e = Expr::Index(Box::new(e), Box::new(ix));
                }
                Some(TokenKind::LParen) => {
                    self.pos += 1;
                    let mut args = Vec::new();
                    if !matches!(self.peek(), Some(TokenKind::RParen)) {
                        loop {
                            let a = self.parse_expr()?;
                            args.push(a);
                            if !self.consume(&TokenKind::Comma) { break; }
                            if matches!(self.peek(), Some(TokenKind::RParen)) { break; }
                        }
                    }
                    self.expect(&TokenKind::RParen, "')'")?;
                    e = Expr::Call(Box::new(e), args);
                }
                _ => break,
            }
        }
        Ok(e)
    }
    fn parse_atom(&mut self) -> Result<Expr, String> {
        match self.peek() {
            Some(TokenKind::Nil) => { self.pos += 1; Ok(Expr::Nil) }
            Some(TokenKind::True) => { self.pos += 1; Ok(Expr::Bool(true)) }
            Some(TokenKind::False) => { self.pos += 1; Ok(Expr::Bool(false)) }
            Some(TokenKind::Int(_)) => {
                if let Some(Token{kind: TokenKind::Int(n), ..}) = self.toks.get(self.pos) {
                    let n = *n; self.pos += 1;
                    Ok(Expr::Int(n))
                } else { unreachable!() }
            }
            Some(TokenKind::Float(_)) => {
                if let Some(Token{kind: TokenKind::Float(f), ..}) = self.toks.get(self.pos) {
                    let f = *f; self.pos += 1;
                    Ok(Expr::Float(f))
                } else { unreachable!() }
            }
            Some(TokenKind::String(_)) => {
                if let Some(Token{kind: TokenKind::String(s), ..}) = self.toks.get(self.pos) {
                    let s = s.clone(); self.pos += 1;
                    Ok(Expr::String(s))
                } else { unreachable!() }
            }
            Some(TokenKind::Byte(_)) => {
                if let Some(Token{kind: TokenKind::Byte(b), ..}) = self.toks.get(self.pos) {
                    let b = *b; self.pos += 1;
                    Ok(Expr::Byte(b))
                } else { unreachable!() }
            }
            Some(TokenKind::Ident(_)) => {
                let s = self.parse_ident()?;
                Ok(Expr::Ident(s))
            }
            Some(TokenKind::Self_) => {
                self.pos += 1;
                Ok(Expr::Ident("self".into()))
            }
            Some(TokenKind::LParen) => {
                self.pos += 1;
                let e = self.parse_expr()?;
                self.expect(&TokenKind::RParen, "')'")?;
                Ok(e)
            }
            Some(TokenKind::LBracket) => {
                self.pos += 1;
                let mut items = Vec::new();
                if !matches!(self.peek(), Some(TokenKind::RBracket)) {
                    loop {
                        let e = self.parse_expr()?;
                        items.push(e);
                        if !self.consume(&TokenKind::Comma) { break; }
                        if matches!(self.peek(), Some(TokenKind::RBracket)) { break; }
                    }
                }
                self.expect(&TokenKind::RBracket, "']'")?;
                Ok(Expr::Array(items))
            }
            Some(TokenKind::AtBracket) => {
                self.pos += 1;
                let mut items: Vec<(String, Expr)> = Vec::new();
                if !matches!(self.peek(), Some(TokenKind::RBracket)) {
                    loop {
                        let key = match self.peek() {
                            Some(TokenKind::Ident(_)) => self.parse_ident()?,
                            Some(TokenKind::String(_)) => {
                                if let Some(Token{kind: TokenKind::String(s), ..}) = self.toks.get(self.pos) {
                                    let s = s.clone(); self.pos += 1;
                                    String::from_utf8_lossy(&s).to_string()
                                } else { unreachable!() }
                            }
                            _ => return Err("expected dict key".into()),
                        };
                        self.expect(&TokenKind::Colon, "':'")?;
                        let v = self.parse_expr()?;
                        items.push((key, v));
                        if !self.consume(&TokenKind::Comma) { break; }
                        if matches!(self.peek(), Some(TokenKind::RBracket)) { break; }
                    }
                }
                self.expect(&TokenKind::RBracket, "']'")?;
                Ok(Expr::Dict(items))
            }
            Some(TokenKind::Function) => {
                self.pos += 1;
                // optional name (parse_stmt would handle named fns differently; here we ignore)
                if matches!(self.peek(), Some(TokenKind::Ident(_))) {
                    // named function; treat like let assignment later
                    let _ = self.parse_ident();
                }
                self.expect(&TokenKind::LParen, "'('")?;
                let mut params = Vec::new();
                if !matches!(self.peek(), Some(TokenKind::RParen)) {
                    loop {
                        if matches!(self.peek(), Some(TokenKind::RParen)) { break; }
                        let name = self.parse_ident()?;
                        params.push(name);
                        if !self.consume(&TokenKind::Comma) { break; }
                    }
                }
                self.expect(&TokenKind::RParen, "')'")?;
                let body = self.parse_block(&[TokenKind::End])?;
                self.expect(&TokenKind::End, "'end'")?;
                Ok(Expr::Function(params, body))
            }
            Some(TokenKind::If) => {
                self.pos += 1;
                let cond = self.parse_expr()?;
                self.expect(&TokenKind::Then, "'then'")?;
                let t = self.parse_block(&[TokenKind::Else, TokenKind::End])?;
                let e = if self.consume(&TokenKind::Else) {
                    self.parse_block(&[TokenKind::End])?
                } else { Vec::new() };
                self.expect(&TokenKind::End, "'end'")?;
                Ok(Expr::If(Box::new(cond), t, e))
            }
            Some(TokenKind::Minus) => { self.parse_unary() }
            _ => Err("expected expression".into()),
        }
    }
}

pub fn parse(toks: &[Token]) -> ParseResult {
    let mut p = Parser { toks, pos: 0 };
    match p.parse_program() {
        Ok(prog) => ParseResult { program: Some(prog), error: None },
        Err(e) => ParseResult { program: None, error: Some(e) },
    }
}
