cat > src/interp.rs <<'RUST_EOF'
use crate::ast::*;
use std::cell::RefCell;
use std::rc::Rc;
use std::collections::HashMap;
use std::io::Write;

#[derive(Clone)]
pub enum Value {
    Nil,
    Bool(bool),
    Int(i64),
    Float(f64),
    String(Vec<u8>),
    Byte(u8),
    Array(Rc<RefCell<Vec<Value>>>),
    Dict(Rc<RefCell<Vec<(String, Value)>>>),
    Function(Rc<Func>),
    Builtin(Rc<BuiltinFn>),
}

pub struct Func {
    pub params: Vec<String>,
    pub body: Vec<Stmt>,
    pub env: Env,
    pub self_val: Option<Value>,
}

pub type BuiltinFn = dyn Fn(&[Value]) -> Value;

#[derive(Clone)]
pub struct Env {
    pub frames: Rc<RefCell<Vec<HashMap<String, Value>>>>,
}

impl Env {
    fn new() -> Self { Env { frames: Rc::new(RefCell::new(vec![HashMap::new()])) } }
    fn push(&self) { self.frames.borrow_mut().push(HashMap::new()); }
    fn pop(&self) { self.frames.borrow_mut().pop(); }
    fn get(&self, name: &str) -> Option<Value> {
        let frames = self.frames.borrow();
        for f in frames.iter().rev() {
            if let Some(v) = f.get(name) { return Some(v.clone()); }
        }
        None
    }
    fn set(&self, name: &str, v: Value) -> bool {
        let mut frames = self.frames.borrow_mut();
        for f in frames.iter_mut().rev() {
            if f.contains_key(name) { f.insert(name.to_string(), v); return true; }
        }
        false
    }
    fn declare(&self, name: &str, v: Value) {
        let mut frames = self.frames.borrow_mut();
        let last = frames.last_mut().unwrap();
        last.insert(name.to_string(), v);
    }
}

enum Flow {
    Normal,
    Return(Value),
    Break,
}

pub fn run(prog: &Program, _src: &str, args: &[String]) -> u8 {
    let env = Env::new();
    setup_std(&env, args);
    let mut flow = Flow::Normal;
    for s in prog {
        exec_stmt(s, &env, &mut flow);
        if !matches!(flow, Flow::Normal) { break; }
    }
    0
}

fn setup_std(env: &Env, args: &[String]) {
    let mut std_entries: Vec<(String, Value)> = Vec::new();

    let args_owned: Vec<String> = args.to_vec();
    let args_fn: Rc<BuiltinFn> = Rc::new(move |_args: &[Value]| {
        let v: Vec<Value> = args_owned.iter().map(|s| Value::String(s.as_bytes().to_vec())).collect();
        Value::Array(Rc::new(RefCell::new(v)))
    });
    std_entries.push(("args".into(), Value::Builtin(args_fn)));

    std_entries.push(("print".into(), Value::Builtin(Rc::new(|args| {
        let stdout = std::io::stdout();
        let mut lock = stdout.lock();
        for (i, a) in args.iter().enumerate() {
            if i > 0 { let _ = lock.write_all(b"\t"); }
            let _ = lock.write_all(&display_value(a, false).into_bytes());
        }
        let _ = lock.flush();
        Value::Nil
    }))));
    std_entries.push(("println".into(), Value::Builtin(Rc::new(|args| {
        let stdout = std::io::stdout();
        let mut lock = stdout.lock();
        for (i, a) in args.iter().enumerate() {
            if i > 0 { let _ = lock.write_all(b"\t"); }
            let _ = lock.write_all(&display_value(a, false).into_bytes());
        }
        let _ = lock.write_all(b"\n");
        let _ = lock.flush();
        Value::Nil
    }))));
    std_entries.push(("len".into(), Value::Builtin(Rc::new(|args| {
        if let Some(v) = args.get(0) {
            match v {
                Value::String(b) => Value::Int(b.len() as i64),
                Value::Array(a) => Value::Int(a.borrow().len() as i64),
                Value::Dict(d) => Value::Int(d.borrow().len() as i64),
                _ => Value::Nil,
            }
        } else { Value::Nil }
    }))));
    std_entries.push(("push".into(), Value::Builtin(Rc::new(|args| {
        if let (Some(Value::Array(a)), Some(v)) = (args.get(0), args.get(1)) {
            a.borrow_mut().push(v.clone());
        }
        Value::Nil
    }))));
    std_entries.push(("pop".into(), Value::Builtin(Rc::new(|args| {
        if let Some(Value::Array(a)) = args.get(0) {
            return a.borrow_mut().pop().unwrap_or(Value::Nil);
        }
        Value::Nil
    }))));
    std_entries.push(("type".into(), Value::Builtin(Rc::new(|args| {
        if let Some(v) = args.get(0) {
            let s: &str = match v {
                Value::Nil => "nil",
                Value::Bool(_) => "bool",
                Value::Int(_) => "int",
                Value::Float(_) => "float",
                Value::String(_) => "string",
                Value::Byte(_) => "byte",
                Value::Array(_) => "array",
                Value::Dict(_) => "dict",
                Value::Function(_) | Value::Builtin(_) => "function",
            };
            Value::String(s.as_bytes().to_vec())
        } else { Value::Nil }
    }))));
    std_entries.push(("to_string".into(), Value::Builtin(Rc::new(|args| {
        if let Some(v) = args.get(0) {
            Value::String(display_value(v, true).into_bytes())
        } else { Value::Nil }
    }))));
    std_entries.push(("exit".into(), Value::Builtin(Rc::new(|args| {
        let code = match args.get(0) {
            Some(Value::Int(n)) => *n as i32,
            _ => 0,
        };
        std::process::exit(code);
    }))));

    env.declare("std", Value::Dict(Rc::new(RefCell::new(std_entries))));
}

pub fn display_value(v: &Value, plain_string: bool) -> String {
    match v {
        Value::Nil => "nil".into(),
        Value::Bool(b) => b.to_string(),
        Value::Int(n) => n.to_string(),
        Value::Float(f) => {
            let s = format!("{}", f);
            if s.contains('.') || s.contains('e') || s.contains('E') { s } else { format!("{}.0", s) }
        }
        Value::String(b) => {
            if plain_string {
                let mut s = String::from("\"");
                for &ch in b {
                    match ch {
                        b'"' => s.push_str("\\\""),
                        b'\\' => s.push_str("\\\\"),
                        b'\n' => s.push_str("\\n"),
                        b'\t' => s.push_str("\\t"),
                        0x20..=0x7e => s.push(ch as char),
                        _ => s.push_str(&format!("\\x{:02x}", ch)),
                    }
                }
                s.push('"');
                s
            } else {
                String::from_utf8_lossy(b).to_string()
            }
        }
        Value::Byte(b) => format!("'{}'", *b as char),
        Value::Array(a) => {
            let a = a.borrow();
            let mut s = String::from("[ ");
            for (i, it) in a.iter().enumerate() {
                if i > 0 { s.push_str(", "); }
                s.push_str(&display_value(it, true));
            }
            s.push_str(" ]");
            s
        }
        Value::Dict(d) => {
            let d = d.borrow();
            let mut s = String::from("@[ ");
            for (i, (k, v)) in d.iter().enumerate() {
                if i > 0 { s.push_str(", "); }
                s.push_str(&format!("\"{}\": {}", k, display_value(v, true)));
            }
            s.push_str(" ]");
            s
        }
        Value::Function(_) | Value::Builtin(_) => "function".into(),
    }
}

fn is_truthy(v: &Value) -> bool {
    match v {
        Value::Nil => false,
        Value::Bool(b) => *b,
        _ => true,
    }
}

fn exec_stmt(s: &Stmt, env: &Env, flow: &mut Flow) {
    match s {
        Stmt::Let(name, None) => { env.declare(name, Value::Nil); }
        Stmt::Let(name, Some(e)) => {
            let v = eval_expr(e, env);
            env.declare(name, v);
        }
        Stmt::Assign(lhs, rhs) => {
            let v = eval_expr(rhs, env);
            assign_to(lhs, v, env);
        }
        Stmt::Return(None) => { *flow = Flow::Return(Value::Nil); }
        Stmt::Return(Some(e)) => { let v = eval_expr(e, env); *flow = Flow::Return(v); }
        Stmt::Break => { *flow = Flow::Break; }
        Stmt::ExprStmt(e) => { let _ = eval_expr(e, env); }
        Stmt::While(cond, body) => {
            loop {
                let c = eval_expr(cond, env);
                if !is_truthy(&c) { break; }
                env.push();
                for s in body {
                    exec_stmt(s, env, flow);
                    if !matches!(flow, Flow::Normal) { break; }
                }
                env.pop();
                if matches!(flow, Flow::Break) { *flow = Flow::Normal; break; }
                if matches!(flow, Flow::Return(_)) { break; }
            }
        }
        Stmt::For(_name, _iter, _body) => {
            // Not implemented fully.
        }
        Stmt::If(cond, t, e) => {
            let c = eval_expr(cond, env);
            env.push();
            if is_truthy(&c) {
                for s in t {
                    exec_stmt(s, env, flow);
                    if !matches!(flow, Flow::Normal) { break; }
                }
            } else {
                for s in e {
                    exec_stmt(s, env, flow);
                    if !matches!(flow, Flow::Normal) { break; }
                }
            }
            env.pop();
        }
    }
}

fn assign_to(lhs: &Expr, v: Value, env: &Env) {
    match lhs {
        Expr::Ident(name) => {
            if !env.set(name, v.clone()) {
                env.declare(name, v);
            }
        }
        Expr::Field(base, name) => {
            let b = eval_expr(base, env);
            if let Value::Dict(d) = b {
                let mut d = d.borrow_mut();
                for (k, ev) in d.iter_mut() {
                    if k == name { *ev = v.clone(); return; }
                }
                d.push((name.clone(), v));
            }
        }
        Expr::Index(base, ix) => {
            let b = eval_expr(base, env);
            let i = eval_expr(ix, env);
            match (b, i) {
                (Value::Array(a), Value::Int(n)) => {
                    let mut a = a.borrow_mut();
                    let idx = if n < 0 { (a.len() as i64 + n) as usize } else { n as usize };
                    if idx < a.len() { a[idx] = v; }
                }
                (Value::Dict(d), Value::String(k)) => {
                    let key = String::from_utf8_lossy(&k).to_string();
                    let mut d = d.borrow_mut();
                    for (ek, ev) in d.iter_mut() {
                        if ek == &key { *ev = v; return; }
                    }
                    d.push((key, v));
                }
                _ => {}
            }
        }
        _ => {}
    }
}

fn eval_expr(e: &Expr, env: &Env) -> Value {
    match e {
        Expr::Nil => Value::Nil,
        Expr::Bool(b) => Value::Bool(*b),
        Expr::Int(n) => Value::Int(*n),
        Expr::Float(f) => Value::Float(*f),
        Expr::String(s) => Value::String(s.clone()),
        Expr::Byte(b) => Value::Byte(*b),
        Expr::Ident(name) => env.get(name).unwrap_or(Value::Nil),
        Expr::Array(items) => {
            let mut vs = Vec::new();
            for it in items { vs.push(eval_expr(it, env)); }
            Value::Array(Rc::new(RefCell::new(vs)))
        }
        Expr::Dict(items) => {
            let mut vs: Vec<(String, Value)> = Vec::new();
            for (k, v) in items { vs.push((k.clone(), eval_expr(v, env))); }
            Value::Dict(Rc::new(RefCell::new(vs)))
        }
        Expr::Index(base, ix) => {
            let b = eval_expr(base, env);
            let i = eval_expr(ix, env);
            match (b, i) {
                (Value::Array(a), Value::Int(n)) => {
                    let a = a.borrow();
                    let idx = if n < 0 { (a.len() as i64 + n) as usize } else { n as usize };
                    a.get(idx).cloned().unwrap_or(Value::Nil)
                }
                (Value::Dict(d), Value::String(k)) => {
                    let key = String::from_utf8_lossy(&k).to_string();
                    let d = d.borrow();
                    for (ek, ev) in d.iter() {
                        if ek == &key { return ev.clone(); }
                    }
                    Value::Nil
                }
                _ => Value::Nil,
            }
        }
        Expr::Field(base, name) => {
            let b = eval_expr(base, env);
            if let Value::Dict(d) = b {
                let d = d.borrow();
                for (k, v) in d.iter() {
                    if k == name { return v.clone(); }
                }
            }
            Value::Nil
        }
        Expr::Call(base, args) => {
            let callee = eval_expr(base, env);
            let mut evaled: Vec<Value> = Vec::new();
            for a in args { evaled.push(eval_expr(a, env)); }
            match callee {
                Value::Builtin(f) => f(&evaled),
                Value::Function(f) => {
                    let call_env = f.env.clone();
                    call_env.push();
                    for (i, p) in f.params.iter().enumerate() {
                        let v = evaled.get(i).cloned().unwrap_or(Value::Nil);
                        call_env.declare(p, v);
                    }
                    let mut flow = Flow::Normal;
                    for s in &f.body {
                        exec_stmt(s, &call_env, &mut flow);
                        if !matches!(flow, Flow::Normal) { break; }
                    }
                    call_env.pop();
                    match flow {
                        Flow::Return(v) => v,
                        _ => Value::Nil,
                    }
                }
                _ => Value::Nil,
            }
        }
        Expr::UnOp(op, inner) => {
            let v = eval_expr(inner, env);
            match (op.as_str(), &v) {
                ("-", Value::Int(n)) => Value::Int(-n),
                ("-", Value::Float(f)) => Value::Float(-f),
                ("not", _) => Value::Bool(!is_truthy(&v)),
                _ => Value::Nil,
            }
        }
