use crate::ast::*;
use std::cell::RefCell;
use std::rc::Rc;
use std::collections::HashMap;
use std::io::Write;

#[derive(Clone)]
pub enum Value {
    Nil,
    Bool(bool),
    Int(i64),
    Float(f64),
    String(Vec<u8>),
    Byte(u8),
    Array(Rc<RefCell<Vec<Value>>>),
