}

pub struct Func {
    pub params: Vec<String>,
    pub body: Vec<Stmt>,
    pub env: Env,
    pub self_val: Option<Value>,
}

pub type BuiltinFn = dyn Fn(&[Value]) -> Value;

#[derive(Clone)]
pub struct Env {
    pub frames: Rc<RefCell<Vec<HashMap<String, Value>>>>,
}

impl Env {
    fn new() -> Self { Env { frames: Rc::new(RefCell::new(vec![HashMap::new()])) } }
    fn push(&self) { self.frames.borrow_mut().push(HashMap::new()); }
    fn pop(&self) { self.frames.borrow_mut().pop(); }
    fn get(&self, name: &str) -> Option<Value> {
        let frames = self.frames.borrow();
        for f in frames.iter().rev() {
            if let Some(v) = f.get(name) { return Some(v.clone()); }
        }
        None
    }
    fn set(&self, name: &str, v: Value) -> bool {
        let mut frames = self.frames.borrow_mut();
        for f in frames.iter_mut().rev() {
            if f.contains_key(name) { f.insert(name.to_string(), v); return true; }
        }
        false
    }
    fn declare(&self, name: &str, v: Value) {
        let mut frames = self.frames.borrow_mut();
        let last = frames.last_mut().unwrap();
        last.insert(name.to_string(), v);
    }
}

enum Flow {
    Normal,
    Return(Value),
    Break,
}

pub fn run(prog: &Program, _src: &str, args: &[String]) -> u8 {
    let env = Env::new();
    setup_std(&env, args);
    let mut flow = Flow::Normal;
    for s in prog {
        exec_stmt(s, &env, &mut flow);
        if !matches!(flow, Flow::Normal) { break; }
    }
    0
}

fn setup_std(env: &Env, args: &[String]) {
    let mut std_entries: Vec<(String, Value)> = Vec::new();

    let args_owned: Vec<String> = args.to_vec();
    let args_fn: Rc<BuiltinFn> = Rc::new(move |_args: &[Value]| {
        let v: Vec<Value> = args_owned.iter().map(|s| Value::String(s.as_bytes().to_vec())).collect();
        Value::Array(Rc::new(RefCell::new(v)))
    });
