        Expr::Ident(name) => {
            if !env.set(name, v.clone()) {
                env.declare(name, v);
            }
        }
        Expr::Field(base, name) => {
            let b = eval_expr(base, env);
            if let Value::Dict(d) = b {
                let mut d = d.borrow_mut();
                for (k, ev) in d.iter_mut() {
                    if k == name { *ev = v.clone(); return; }
                }
                d.push((name.clone(), v));
            }
        }
        Expr::Index(base, ix) => {
            let b = eval_expr(base, env);
            let i = eval_expr(ix, env);
            match (b, i) {
                (Value::Array(a), Value::Int(n)) => {
                    let mut a = a.borrow_mut();
                    let idx = if n < 0 { (a.len() as i64 + n) as usize } else { n as usize };
