                Value::Array(_) => "array",
                Value::Dict(_) => "dict",
                Value::Function(_) | Value::Builtin(_) => "function",
            };
            Value::String(s.as_bytes().to_vec())
        } else { Value::Nil }
    }))));
    std_entries.push(("to_string".into(), Value::Builtin(Rc::new(|args| {
        if let Some(v) = args.get(0) {
            Value::String(display_value(v, true).into_bytes())
        } else { Value::Nil }
    }))));
    std_entries.push(("exit".into(), Value::Builtin(Rc::new(|args| {
        let code = match args.get(0) {
            Some(Value::Int(n)) => *n as i32,
            _ => 0,
        };
        std::process::exit(code);
    }))));

    env.declare("std", Value::Dict(Rc::new(RefCell::new(std_entries))));
}

pub fn display_value(v: &Value, plain_string: bool) -> String {
    match v {
        Value::Nil => "nil".into(),
        Value::Bool(b) => b.to_string(),
        Value::Int(n) => n.to_string(),
        Value::Float(f) => {
            let s = format!("{}", f);
            if s.contains('.') || s.contains('e') || s.contains('E') { s } else { format!("{}.0", s) }
        }
        Value::String(b) => {
            if plain_string {
                let mut s = String::from("\"");
                for &ch in b {
                    match ch {
                        b'"' => s.push_str("\\\""),
                        b'\\' => s.push_str("\\\\"),
                        b'\n' => s.push_str("\\n"),
                        b'\t' => s.push_str("\\t"),
                        0x20..=0x7e => s.push(ch as char),
                        _ => s.push_str(&format!("\\x{:02x}", ch)),
                    }
                }
                s.push('"');
                s
            } else {
                String::from_utf8_lossy(b).to_string()
            }
        }
        Value::Byte(b) => format!("'{}'", *b as char),
        Value::Array(a) => {
            let a = a.borrow();
            let mut s = String::from("[ ");
            for (i, it) in a.iter().enumerate() {
                if i > 0 { s.push_str(", "); }
                s.push_str(&display_value(it, true));
            }
            s.push_str(" ]");
            s
        }
        Value::Dict(d) => {
            let d = d.borrow();
            let mut s = String::from("@[ ");
            for (i, (k, v)) in d.iter().enumerate() {
                if i > 0 { s.push_str(", "); }
                s.push_str(&format!("\"{}\": {}", k, display_value(v, true)));
            }
            s.push_str(" ]");
            s
        }
        Value::Function(_) | Value::Builtin(_) => "function".into(),
    }
}

fn is_truthy(v: &Value) -> bool {
    match v {
        Value::Nil => false,
        Value::Bool(b) => *b,
        _ => true,
    }
}

fn exec_stmt(s: &Stmt, env: &Env, flow: &mut Flow) {
    match s {
        Stmt::Let(name, None) => { env.declare(name, Value::Nil); }
        Stmt::Let(name, Some(e)) => {
            let v = eval_expr(e, env);
            env.declare(name, v);
        }
        Stmt::Assign(lhs, rhs) => {
            let v = eval_expr(rhs, env);
            assign_to(lhs, v, env);
        }
        Stmt::Return(None) => { *flow = Flow::Return(Value::Nil); }
        Stmt::Return(Some(e)) => { let v = eval_expr(e, env); *flow = Flow::Return(v); }
        Stmt::Break => { *flow = Flow::Break; }
        Stmt::ExprStmt(e) => { let _ = eval_expr(e, env); }
        Stmt::While(cond, body) => {
            loop {
                let c = eval_expr(cond, env);
                if !is_truthy(&c) { break; }
                env.push();
                for s in body {
                    exec_stmt(s, env, flow);
                    if !matches!(flow, Flow::Normal) { break; }
                }
                env.pop();
                if matches!(flow, Flow::Break) { *flow = Flow::Normal; break; }
                if matches!(flow, Flow::Return(_)) { break; }
            }
        }
        Stmt::For(_name, _iter, _body) => {
            // Not implemented fully.
        }
        Stmt::If(cond, t, e) => {
            let c = eval_expr(cond, env);
            env.push();
            if is_truthy(&c) {
                for s in t {
                    exec_stmt(s, env, flow);
                    if !matches!(flow, Flow::Normal) { break; }
                }
            } else {
                for s in e {
                    exec_stmt(s, env, flow);
                    if !matches!(flow, Flow::Normal) { break; }
                }
            }
            env.pop();
        }
    }
}

fn assign_to(lhs: &Expr, v: Value, env: &Env) {
    match lhs {
        Expr::Ident(name) => {
            if !env.set(name, v.clone()) {
                env.declare(name, v);
            }
        }
        Expr::Field(base, name) => {
            let b = eval_expr(base, env);
            if let Value::Dict(d) = b {
                let mut d = d.borrow_mut();
                for (k, ev) in d.iter_mut() {
                    if k == name { *ev = v.clone(); return; }
                }
                d.push((name.clone(), v));
            }
        }
        Expr::Index(base, ix) => {
            let b = eval_expr(base, env);
            let i = eval_expr(ix, env);
            match (b, i) {
                (Value::Array(a), Value::Int(n)) => {
                    let mut a = a.borrow_mut();
                    let idx = if n < 0 { (a.len() as i64 + n) as usize } else { n as usize };
                    if idx < a.len() { a[idx] = v; }
                }
                (Value::Dict(d), Value::String(k)) => {
                    let key = String::from_utf8_lossy(&k).to_string();
                    let mut d = d.borrow_mut();
                    for (ek, ev) in d.iter_mut() {
                        if ek == &key { *ev = v; return; }
                    }
                    d.push((key, v));
                }
                _ => {}
            }
        }
        _ => {}
    }
}

fn eval_expr(e: &Expr, env: &Env) -> Value {
    match e {
        Expr::Nil => Value::Nil,
        Expr::Bool(b) => Value::Bool(*b),
        Expr::Int(n) => Value::Int(*n),
        Expr::Float(f) => Value::Float(*f),
        Expr::String(s) => Value::String(s.clone()),
        Expr::Byte(b) => Value::Byte(*b),
        Expr::Ident(name) => env.get(name).unwrap_or(Value::Nil),
        Expr::Array(items) => {
            let mut vs = Vec::new();
            for it in items { vs.push(eval_expr(it, env)); }
            Value::Array(Rc::new(RefCell::new(vs)))
        }
        Expr::Dict(items) => {
            let mut vs: Vec<(String, Value)> = Vec::new();
            for (k, v) in items { vs.push((k.clone(), eval_expr(v, env))); }
            Value::Dict(Rc::new(RefCell::new(vs)))
        }
        Expr::Index(base, ix) => {
            let b = eval_expr(base, env);
            let i = eval_expr(ix, env);
            match (b, i) {
                (Value::Array(a), Value::Int(n)) => {
                    let a = a.borrow();
                    let idx = if n < 0 { (a.len() as i64 + n) as usize } else { n as usize };
                    a.get(idx).cloned().unwrap_or(Value::Nil)
                }
                (Value::Dict(d), Value::String(k)) => {
                    let key = String::from_utf8_lossy(&k).to_string();
                    let d = d.borrow();
                    for (ek, ev) in d.iter() {
                        if ek == &key { return ev.clone(); }
                    }
                    Value::Nil
                }
                _ => Value::Nil,
            }
        }
        Expr::Field(base, name) => {
            let b = eval_expr(base, env);
            if let Value::Dict(d) = b {
                let d = d.borrow();
                for (k, v) in d.iter() {
                    if k == name { return v.clone(); }
                }
            }
            Value::Nil
        }
        Expr::Call(base, args) => {
            let callee = eval_expr(base, env);
            let mut evaled: Vec<Value> = Vec::new();
            for a in args { evaled.push(eval_expr(a, env)); }
            match callee {
                Value::Builtin(f) => f(&evaled),
                Value::Function(f) => {
                    let call_env = f.env.clone();
                    call_env.push();
                    for (i, p) in f.params.iter().enumerate() {
                        let v = evaled.get(i).cloned().unwrap_or(Value::Nil);
                        call_env.declare(p, v);
                    }
                    let mut flow = Flow::Normal;
                    for s in &f.body {
                        exec_stmt(s, &call_env, &mut flow);
                        if !matches!(flow, Flow::Normal) { break; }
                    }
                    call_env.pop();
                    match flow {
                        Flow::Return(v) => v,
                        _ => Value::Nil,
                    }
                }
                _ => Value::Nil,
            }
        }
        Expr::UnOp(op, inner) => {
            let v = eval_expr(inner, env);
            match (op.as_str(), &v) {
                ("-", Value::Int(n)) => Value::Int(-n),
                ("-", Value::Float(f)) => Value::Float(-f),
                ("not", _) => Value::Bool(!is_truthy(&v)),
                _ => Value::Nil,
            }
        }
        Expr::BinOp(op, a, b) => {
            let av = eval_expr(a, env);
            if op == "or" {
                return if is_truthy(&av) { av } else { eval_expr(b, env) };
            }
            if op == "and" {
                return if !is_truthy(&av) { av } else { eval_expr(b, env) };
            }
            let bv = eval_expr(b, env);
            bin_op(op, &av, &bv)
        }
        Expr::Function(params, body) => {
            Value::Function(Rc::new(Func { params: params.clone(), body: body.clone(), env: env.clone(), self_val: None }))
        }
        Expr::If(cond, t, e) => {
            let c = eval_expr(cond, env);
            env.push();
            let result = if is_truthy(&c) {
                eval_block_value(t, env)
            } else {
                eval_block_value(e, env)
            };
            env.pop();
            result
        }
    }
}

fn eval_block_value(stmts: &[Stmt], env: &Env) -> Value {
    let mut last = Value::Nil;
    let mut flow = Flow::Normal;
    for s in stmts {
        if let Stmt::ExprStmt(e) = s {
            last = eval_expr(e, env);
        } else {
            exec_stmt(s, env, &mut flow);
            if let Flow::Return(v) = &flow { return v.clone(); }
            last = Value::Nil;
        }
    }
    last
}

fn bin_op(op: &str, a: &Value, b: &Value) -> Value {
    match op {
        "+" => num_op(a, b, |x,y| x.wrapping_add(y), |x,y| x+y),
        "-" => num_op(a, b, |x,y| x.wrapping_sub(y), |x,y| x-y),
        "*" => num_op(a, b, |x,y| x.wrapping_mul(y), |x,y| x*y),
        "/" => match (a, b) {
            (Value::Int(x), Value::Int(y)) if *y != 0 => Value::Int(x/y),
            (Value::Float(x), Value::Float(y)) => Value::Float(x/y),
            (Value::Int(x), Value::Float(y)) => Value::Float(*x as f64 / y),
            (Value::Float(x), Value::Int(y)) => Value::Float(x / *y as f64),
            _ => Value::Nil,
        }
        "%" => match (a, b) {
            (Value::Int(x), Value::Int(y)) if *y != 0 => Value::Int(x % y),
            _ => Value::Nil,
        }
        "++" => match (a, b) {
            (Value::String(x), Value::String(y)) => {
                let mut v = x.clone(); v.extend_from_slice(y); Value::String(v)
            }
            _ => Value::Nil,
        }
        "==" => Value::Bool(val_eq(a, b)),
        "!=" => Value::Bool(!val_eq(a, b)),
        "<" => Value::Bool(val_cmp(a,b) == std::cmp::Ordering::Less),
        "<=" => Value::Bool(val_cmp(a,b) != std::cmp::Ordering::Greater),
        ">" => Value::Bool(val_cmp(a,b) == std::cmp::Ordering::Greater),
        ">=" => Value::Bool(val_cmp(a,b) != std::cmp::Ordering::Less),
        _ => Value::Nil,
    }
}

fn num_op(a: &Value, b: &Value, i: fn(i64,i64)->i64, f: fn(f64,f64)->f64) -> Value {
    match (a, b) {
        (Value::Int(x), Value::Int(y)) => Value::Int(i(*x, *y)),
        (Value::Float(x), Value::Float(y)) => Value::Float(f(*x, *y)),
        (Value::Int(x), Value::Float(y)) => Value::Float(f(*x as f64, *y)),
        (Value::Float(x), Value::Int(y)) => Value::Float(f(*x, *y as f64)),
        _ => Value::Nil,
    }
}

fn val_eq(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Nil, Value::Nil) => true,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::Int(x), Value::Int(y)) => x == y,
        (Value::Float(x), Value::Float(y)) => x == y,
        (Value::Int(x), Value::Float(y)) => (*x as f64) == *y,
        (Value::Float(x), Value::Int(y)) => *x == (*y as f64),
        (Value::String(x), Value::String(y)) => x == y,
        (Value::Byte(x), Value::Byte(y)) => x == y,
        _ => false,
    }
}

fn val_cmp(a: &Value, b: &Value) -> std::cmp::Ordering {
    use std::cmp::Ordering::*;
    match (a, b) {
        (Value::Int(x), Value::Int(y)) => x.cmp(y),
        (Value::Float(x), Value::Float(y)) => x.partial_cmp(y).unwrap_or(Equal),
        (Value::Int(x), Value::Float(y)) => (*x as f64).partial_cmp(y).unwrap_or(Equal),
        (Value::Float(x), Value::Int(y)) => x.partial_cmp(&(*y as f64)).unwrap_or(Equal),
        (Value::String(x), Value::String(y)) => x.cmp(y),
        _ => Equal,
    }
}
